package com.kaipai.integration.ai.profileimport; import com.kaipai.service.ai.profileimport.ProfileImportHttpTransport; import java.net.URI; import java.net.http.*; import java.time.Duration; import org.springframework.stereotype.Component;
@Component public class DeepSeekProfileImportHttpTransport implements ProfileImportHttpTransport { public String post(String endpoint,String apiKey,String body){try{HttpRequest req=HttpRequest.newBuilder(URI.create(endpoint)).timeout(Duration.ofSeconds(60)).header("Authorization","Bearer "+apiKey).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String> response=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("provider status");return response.body();}catch(java.net.http.HttpTimeoutException e){throw new ProfileImportHttpTransport.Timeout();}catch(Exception e){throw new IllegalStateException(e);}}}
